-- Momo v3.50 — Support Chat Actions for reviewed Knowledge drafts
-- Run in Supabase SQL Editor, then reindex Momo Support documentation from
-- Admin > Support > Knowledge Base > Reindexar documentação.
-- No schema changes are required.

update public.knowledge_entries
set
  content = 'The Knowledge Base is managed by an organization Owner. In Portal > Knowledge Base, an Owner can add manual knowledge with Title, Category and Content, choose Public or Internal visibility, choose Published or Draft status, and save the entry. A public published manual entry is embedded/indexed when it is saved, so Reindex is not mandatory after every manual entry; Reindex is available to refresh public published knowledge after broader changes. Website knowledge can also be generated by analysing the organization public website. Running website analysis again replaces website-sourced entries while preserving manual entries. Before saving new manual business information, Momo Support should recommend that the client paste the raw information into Support so it can be checked and prepared as a clear Knowledge Base draft. When the reviewed draft is ready, the Portal shows chat actions below it. An authenticated Owner saves it by pressing Add to Knowledge; a normal chat message such as yes, save it or podes adicionar does not perform the write. The I want to edit action helps the client continue revising the draft. Members may prepare wording with Support but cannot save Knowledge Base changes.',
  embedding = null,
  updated_at = now()
where agent_key = 'momo-support'
  and slug = 'momo-support-knowledge-base';

update public.knowledge_entries
set
  content = 'Momo Support can help an authenticated client prepare wording before a manual Knowledge Base entry is saved. The client can paste raw business information into Support. Support may rewrite only for clarity, structure and self-contained wording; it must preserve every supplied fact, condition, exception, limitation, name, price, amount, date, duration, unit, location and policy, and it must not invent or silently remove information. If the source is ambiguous, contradictory or missing context needed for a reliable statement, Support asks a concise clarifying question before producing the final draft. Good Knowledge Base wording is factual, direct, self-contained and focused on one coherent topic where practical. When ready, Support shows the exact Title, Category and Content for review. The Portal then shows Add to Knowledge and I want to edit chat actions. Only an authenticated Owner can use Add to Knowledge; the button is the explicit save confirmation and creates the entry as Public + Published with its embedding immediately. A normal text message does not save the draft. If the client requests a correction, Support revises and shows the complete draft again before the save action is used. Members can prepare and review drafts but cannot save Knowledge Base changes. The automatic Support save flow does not currently create Internal or Draft entries; those visibility/status choices remain available through Portal > Knowledge Base.',
  embedding = null,
  updated_at = now()
where agent_key = 'momo-support'
  and slug = 'momo-support-knowledge-drafting';
